package com.smritisathi.app.core;
import android.content.*;import android.net.*;import android.database.*;import com.google.gson.*;import java.util.*;
public class SyncManager {public static void sync(Context c){String token=Session.token(c);if(token.isEmpty())return;OfflineDb db=new OfflineDb(c);Cursor cur=db.getReadableDatabase().query("sessions",null,"synced=0",null,null,null,"id ASC");while(cur.moveToNext()){JsonObject b=new JsonObject();b.addProperty("patientId",cur.getString(cur.getColumnIndexOrThrow("patientId")));b.addProperty("gameType",cur.getString(cur.getColumnIndexOrThrow("gameType")));b.addProperty("difficulty",cur.getString(cur.getColumnIndexOrThrow("difficulty")));b.addProperty("score",cur.getInt(cur.getColumnIndexOrThrow("score")));b.addProperty("accuracy",cur.getInt(cur.getColumnIndexOrThrow("accuracy")));b.addProperty("reactionTimeMs",cur.getLong(cur.getColumnIndexOrThrow("reactionTimeMs")));b.addProperty("durationSeconds",cur.getInt(cur.getColumnIndexOrThrow("durationSeconds")));long id=cur.getLong(cur.getColumnIndexOrThrow("id"));ApiClient.request("POST","/sessions",token,b,(ok,d,e)->{if(ok){OfflineDb h=new OfflineDb(c);ContentValues v=new ContentValues();v.put("synced",1);h.getWritableDatabase().update("sessions",v,"id=?",new String[]{String.valueOf(id)});h.close();}});}cur.close();db.close();}public static void register(Context c){ConnectivityManager cm=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);if(android.os.Build.VERSION.SDK_INT>=24)cm.registerDefaultNetworkCallback(new ConnectivityManager.NetworkCallback(){public void onAvailable(Network n){sync(c);}});}}
